import sys

def find_gcd_subsequence(n, i):
    seq = [i] * n
    for j in range(1, n):
        for k in range(j-1, 1, -1):
            new_gcd = math.gcd(seq[k-1], seq[k])
            if new_gcd > 1:
                seq[k-1] //= new_gcd
                break
    for i in range(n):
        seq[i] *= 10 ** (n - i - 1)
    return list(seq)

def solution(n):
    gcd_val = 1
    output = []
    i = 1
    while gcd_val != n:
        seq = find_gcd_subsequence(n, i)
        for j in range(len(seq)):
            gcd_val = math.gcd(gcd_val, seq[j])
        if gcd_val != n:
            output.append(i)
            seq = find_gcd_subsequence(n, i)
            for j in range(len(seq)):
                gcd_val = math.gcd(gcd_val, seq[j])
        i += 1
    if len(output) == 1:
        output.append(n)
    return output

def main():
    T = int(input())
    for _ in range(T):
        N = int(input())
        print(" ".join(map(str, solution(N))))

