from math import gcd
from collections import Counter

def lcm(a, b):
    return (a // gcd(a, b)) * b

def find_smallest_common_multiple(arr, mod):
    lcm_val = arr[0]
    for value in arr[1:]:
        lcm_val = lcm(lcm_val, value)
    return lcm_val % mod

def solve_problem(arr, N, K, M, mod):
    count = Counter(arr)
    prefix_sum = []
    for num, freq in count.items():
        prefix_sum.append((prefix_sum[-1] * K + num * freq + freq) % mod)
    total_subseq = 0
    for num in arr:
        common_num = find_smallest_common_multiple(arr, mod)
        leading_zeroes = arr.count(num)
        suffix = prefix_sum.pop(-leading_zeroes)
        start = (prefix_sum[0] - (num * freq + freq - K)) % mod
        total_subseq = (total_subseq + (mod - start) * suffix * freq % mod * (freq - 1) % mod * inv(freq) % mod * (K - freq) * inv(freq + 1) % mod) % mod
    return total_subseq

def inv(n):
    return pow(n, mod - 2, mod)

for _ in range(int(input())):
    N, K, M = map(int, input().split())
    arr = list(map(int, input().split()))
    print(solve_problem(arr, N, K, M, 1000000007))
