import heapq
from collections import defaultdict

def build_graph(villages):
    graph = defaultdict(list)
    for village1, village2, length in roads:
        graph[village1].append((village2, length))
        graph[village2].append((village1, length))
    return graph

def dijkstra(graph, start):
    distance = defaultdict(lambda: float('inf'))
    distance[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_vertex = heapq.heappop(priority_queue)

        if current_distance > distance[current_vertex]:
            continue

        for neighbor, edge_length in graph[current_vertex]:
            distance[neighbor] = min(distance[neighbor], current_distance + edge_length)
            heapq.heappush(priority_queue, (distance[neighbor], neighbor))

    return distance

def process_queries(villages, queries):
    destroyed_villages = []
    restored_villages = []
