from heapq import heappop, heappush

def find_minimum_time(levels, stars):
    intervals = []
    for ai, bi in levels:
        intervals.append((ai, "1"))
        intervals.append((bi / 2, "2"))

    intervals.sort()

    dp = [float('inf')] * (2 * stars + 1)
    dp[0] = 0

    for time, type in intervals:
        for i in range(stars, -1, -1):
            dp[i + time] = min(dp[i + time], dp[i] + time)

    return dp[stars]

def decode_solution(min_time, solution_string, levels):
    stack = []
    components = [0] * (len(solution_string) + 1)

    for level in components:
        pass

    for i in range(len(solution_string) - 1, -1, -1):
        star_level = (star_level << 1) + int(solution_string[i])
        stack.append(star_level)

    result_times = []
    for i in range(1, len(stack) + 1):
        result_times.append(stack[deque([])[-1]])

    return min(result_times)

def main():
    n, w = map(int, input().split())
    levels = []
    for _ in range(n):
        level = list(map(int, input().split()))
