    result_time = 0

    for level in levels:
        if level[0] <= stars <= level[1]:
            stars = level[1]
        if level[0] <= stars < level[1] or level[1] <= stars:
            if len(stack) - 1 <= result_time <= stars:
                stack.append((result_time << 1) + 1)
            result_time += 1

    return min_time, decode_solution(min_time, solution_string)

