def max_palindrome_score(length, points, string):
    dp = [[-1] * (length + 1) for _ in range(length + 1)]
    for i in range(length):
        dp[i][1] = points[i]
    for i in range(length):
        for j in range(2, length + 1):
            if string[i:] == string[i:][::-1]:
                dp[i][j] = max(dp[i][j - 1], j * points[i])
            else:
                dp[i][j] = dp[i + 1][j - 1]
    return max(dp[0][length - 1], dp[0][-1])

