class RoadGraph:
    def __init__(self, n):
        self.n = n
        self.roads = list()
        self.road_length = [0] * n
        self.unrestored = set()

    def add_road(self, ai, bi, length):
        edge = (ai, bi)
        if edge in self.roads:
            self.roads.remove(edge)
        self.roads.append(edge)
        self.roads.append((bi, ai))
        self.road_length[ai - 1] += length
        self.road_length[bi - 1] += length

    def restore(self, village):
        self.unrestored.discard(village)
        if village in self.roads:
            self.roads.remove((village, village + 1))
            self.roads.append((village, village + 1))

    def destroy(self, village):
        self.unrestored.discard(village)
        if village + 1 in self.roads:
            self.roads.remove((village, village + 1))

def main():
    n = int(input())
    road_graph = RoadGraph(n)
    for _ in range(n - 1):
