from collections import defaultdict

def minimum_bricks(grid: List[str]) -> int:
    row = defaultdict(int)
    for i, r in enumerate(grid):
        j = 0
        for k in range(len(grid[0])):
            if r[k] == "#":
                row[j] += 1
                if k < len(r) - 1:
                    j += 1
                else:
                    break
            else:
                j += 1

    num_traversed = defaultdict(int)

    def traverse(row):
        curr_tracked = 1
        for i in range(len(row)):
            if row[i] == 0:
                curr_tracked = curr_tracked - row[i] + traverse(row[:i])
                num_traversed[curr_tracked] += row[i]
            yield curr_tracked

    for i in row:
      yield row[i]

    traversal = list(traverse(row))
    return min(traversal)
