from itertools import product, count

def is_possible(source, target, length_source, length_target):
    for i in range(2**length_source):
        transitions = [ord('A') == ord(c) for c in bin(i)[2:] if c]
        if sum(transitions) % 2 == sum(partial_map(lambda x: (ord('B') == ord(x) or ord('C') == ord(x)), transitions)): 
            changes = 0
            for j in range(length_source):
                make_transition = (transitions[j] + transitions[-1 - j] - transitions[-1])
                if make_transition > 0:
                    if source[j - 1] not in ('A', 'C'):
                        breaks = make_transition % 3
                        make_transition = 3 - make_transition
                        for k in range(breaks):
                            source = source[:j - 1] + source[j:] * make_transition - target[j - k]
                            changes += 1
                            if source[:length_target-j+k+1] != target:j - 1
                            if source[:length_target-j+k+1] != target[:length_target-j+k+1]:
                                break
                            make_transition += make_transition // 3
                            if make_transition % 3 == 0:
                                break 
                else:
                    source.replace(source[j-1], target[j-1 - make_transition])
                    changes += make_transition
    return {
        source[:length_target], source[length_target-1],
        target[:length_target], target[length_target-1]
    } == {' ', char}

def solve(source, target, length_source, length_target):
    q = []
    for i in range(length_target):
        q.append([
            *[int(c != target[i]), i + 1] for c in source 
        ], 
        *[int(c != target[i]) for c in target])
    first_queries = filter(is_possible, product(*q), count(1))
    return ['1' if is_possible(*l) else '0' for l in first_queries]
