import collections

def find_shortest_path(edges, n, edges_count):
    parent = list(range(n))
    distance = [0] + [float('inf')] * n

    def find(set_id):
        if parent[set_id] != set_id:
            parent[set_id] = find(parent[set_id])
        return parent[set_id]

    for _ in range(1, n + 1):
        parent[_] = _  # Initialize parent to itself

    for i, j, d in edges[:edges_count]:
        if find(i) != find(j):
            parent[find(j)] = find(i)  # Union 
            distance[find(j)] = d

    return distance

def query_manager(history, queries, edges, n):
    shortest_path = find_shortest_path(history, n, len(edges))
    result = []

    for query in queries:
        if query == '?':
            if len(result) == 0:
                result.append(shortest_path[1])
                continue
            result_str = ''
            for d in result:
                result_str += str(-1 * d) + ' '
            print(result_str.rstrip(' '))
        elif query == '+':
