            result.append(shortest_path[m])
        elif query == '-':
            m = int(input().strip())
            for i in range(n):
                parent = list(range(n))
                current_dist = [0] + [float('inf')] * n
                r = find_shortest_path([[-1 * d, i] for i, dist in enumerate(shortest_path) if dist > 0], n, len(edges))
                for idx in [-1, r, m]:
                    for s, t, d in edges:
                        if idx == -1:
                            x = s
                        else:
