def min_bricks_width(grid):
    width_counts = {}
    n, m = len(grid), len(grid[0])
    for row in grid:
        open_positions = {i for i, c in enumerate(row) if c == "."}
        for i in open_positions:
            width = i
            while width > 0:
                if row[:width] in width_counts:
                    return len(width_counts[row[:width]])
                row_counts = (i, width)
                width_counts[row_counts[:]] = 1
                width = width - 1

    return len(width_counts)

def min_bricks_height(grid):
    height_counts = {}
    n, m = len(grid), len(grid[0])
    for row in grid:
        open_positions = {i for i, c in enumerate(row) if c == "."}
        for i in open_positions:
            height = i
            while height > 0:
                if row[:height] in height_counts:
                    return len(height_counts[row[:height]])
                row_counts = (height, i)
                height_counts[row_counts[:]] = 1
                height = height - 1

    return len(height_counts)

def min_bricks(grid):
    return min(min_bricks_width(grid), min_bricks_height(grid))

