def find_longest_palindrome(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 1:
                dp[i][j] = 1
            elif length == 2:
                dp[i][j] = (s[i] == s[j])
            else:
                dp[i][j] = dp[i + 1][j - 1] and (s[i] == s[j])
            if dp[i][j]:
                return dp[i][j]
    return 0

def delete_palindromes(score, char_list):
    used_chars = set()
    points = 0

    while char_list:
        for i in range(len(char_list)):
            k = char_list[i]
            if k not in used_chars:
                for j in range(len(char_list)):
                    cost = k
                    if used_chars:
                        prefix = char_list[:j][::-1]
                        cost += score[find_longest_palindrome(prefix)]
                    seq = char_list[j:]
                    after = str(seq.pop())
                    score_to_add = 0
                    if after == after[::-1] and after != '' and after not in used_chars:
                        after_sym = seq.pop()
                        score_to_add = score[find_longest_palindrome(seq)]
                        if after_sym == after[-1]:
                            sequence_list = [seq] + [after_sym]
                            for sk in score_to_add:
                                pieces = [l + 's' + r for l in sequence_list for r in sequence_list]
                                for p in pieces:
                                    skip = char_list[:i] + char_list[i+1:]
                                    skip.insert(i, p)
                                    cost += sk
                                    used_chars.add(p)
                                    i += len(p)
                                del cost
                            if skip:
                                points += cost
                    score_to_add += score[6]
                    used_chars.add(k)
        score *= 3
        used_chars.clear()
        if len(char_list) == 5:
            break

    return points

