        elif gate == 'X' or gate == 'x':
            output |= str(bit1 ^ bit2)
        elif gate.startswith('NOT '):
            output |= str(1 - int(edge[0]))
    return int(output)

def process_gates(w, n, m, inputs, gates):
    m_outputs = [0] * m

    # Convert each input to words of length w
    words = []
    for i in range(n):
        words.append(''.join(map(str, [bool(int(x)) for x in list(format(inputs[i], f'0{w}b'))])))

    for wg in gates:
        gate_function = ''
        for char in wg[:w]:
            gate_function += str(1 - int(char))
        for assign in product(range(2**w), repeat=2):
            for x, y in product(assign, repeat=2):
                if bit_gate_function(words[x], words[y], gate_function) == '0':
                    m_outputs[int(wg[w:], 2) - 1] += 1

    return m_outputs

