from collections import defaultdict

def findValidSubsequences(n, k, m, A):
    MOD = 10**9 + 7
    dp = [defaultdict(int) for _ in range(n+1)]
    prev = defaultdict(int)
    for i in range(n):
        dp[i+1] = {0: 1}
        for j in range(1, m+1):
            for val in prev:
                if val < i and A[j] % (i+1) == j:
                    dp[i+1][j % (i+1)] += prev[val]
                    dp[i+1][j % (i+1)] %= MOD
            for val in prev:
                if val < i and A[j] % (i+1) == (i-j+1) * (i-j) % (i+1):
                    dp[i+1][(i+1) % (i+1)] += prev[val]
                    dp[i+1][(i+1) % (i+1)] %= MOD
        if A[j] % (i+1) < i:
            dp[i+1][A[j] % (i+1)] += 1
            dp[i+1][A[j] % (i+1)] %= MOD
        prev[A[j]] += 1
    return sum(dp[n][val] for val in dp[n]) % MOD

