from collections import deque

def make_bfs(initial_string, target_string):
    """Perform BFS to recognize strings based on given transition"""
    initial_bfs = deque()
    char_bfs_dict = {}

    for char in initial_string:
        initial_bfs.append(char)
        char_bfs_dict.setdefault(char, deque()).append(0)

    def bfs(inv_astc_acb):
        inv_ast = 0
        inv_acb = 0
        if inv_astc_acb in char_bfs_dict:
            inv_ast, inv_acb = char_bfs_dict[inv_astc_acb]
        return {'a': inv_acb, 'b': inv_ast}

    while len(initial_bfs) != 0:
        char = initial_bfs.popleft()
        for transition in ['BC', 'AB', 'AC']:
            if char + transition in target_string:
                if transition in char_bfs_dict:
                    char_bfs_dict[char].appendleft(bfs(transition))
                else:
                    char_bfs_dict[char] = deque([bfs(transition)])

    return char_bfs_dict

def can_make_t_from_s(start, start_1, start_2, end, end_1, end_2):
    """Check if can make target in-between the given strings"""
    trans = make_bfs(start, start_1)
    if 'a' not in trans:
        return False
    inv_acb = trans['a']

    trans = make_bfs(start + end, start_2 + end_1)
    if 'a' not in trans:
        return False
    inv_ast = trans['a']

    start_ter_vals = inv_acb['b'] & inv_ast & (1 << (start_1 - end_1 + 1))
    if start_ter_vals == 0:
        return False
    return start_ter_vals != (1 << start_1 - end_1 + 1)

